Given a 2D matrix mat[][] of size n x m. Modify the matrix such that if mat[i][j] is 0, all the elements in the i-th row and j-th column are set to 0.Examples:Input: mat[][] = [[1, -1, 1], [-1, 0, 1], [1, -1, 1]]Output: [[1, 0, 1], [0, 0, 0], [1, 0, 1]]Explanation: mat[1][1] = 0, so all elements in row 1 and column 1 are updated to zeroes.Input: mat[][] = [[0, 1, 2, 0], [3, 4, 0, 2], [1, 3, 1, 5]]Output: [[0, 0, 0, 0], [0, 0, 0, 0], [0, 3, 0, 0]]Explanation: mat[0][0], mat[1][2] and mat[0][3] are 0s, so all elements in row 0, row 1, column 0, column 2 and column 3 are updated to zeroes.Try It YourselfTable of Content[Naive Approach] Using Two Auxiliary Arrays - O(n*m) Time and O(n+m) Space[Expected Approach] Using First Row and Column - O(n*m) Time and O(1) Space[Naive Approach] Using Two Auxiliary Arrays - O(n*m) Time and O(n+m) SpaceThe idea is to maintain two additional arrays, say rows[] and cols[] to store the rows and columns which contains at least one element equal to 0. So, first traverse the entire matrix and for each mat[i][j] = 0, mark rows[i] = true and cols[j] = true. Now in the second traversal, for each cell (i, j), if either rows[i] or cols[j] is marked as true, update mat[i][j] = 0 else continue to the next cell.
            C++

    #include <iostream>
#include <vector>
using namespace std;

void setMatrixZeroes(vector<vector<int>> &mat) {
    int n = mat.size(), m = mat[0].size();

    // To store which rows and columns are
    // supposed to mark with zeroes
    vector<bool> rows(n, false), cols(m, false);

    // Traverse the matrix to fill rows[] and cols[]
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {

            // If the cell contains zero then mark
            // its row and column as zero
            if (mat[i][j] == 0) {
                rows[i] = true;
                cols[j] = true;
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {

            // Mark cell (i, j) with zero if either
            // of rows[i] or cols[j] is true
            if (rows[i] || cols[j])
                mat[i][j] = 0;
        }
    }
}

int main() {
    vector<vector<int> > mat = { { 0, 1, 2, 0 },
                                 { 3, 4, 0, 2 },
                                 { 1, 3, 1, 5 } };

    setMatrixZeroes(mat);
    for (int i = 0; i < mat.size(); i++) {
        for (int j = 0; j < mat[0].size(); j++) {
            cout << mat[i][j] << " ";
        }
        cout << endl;
    }
    return 0;
}


